def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = []
    for r in range(rows):
        count = 0
        for c in range(cols):
            if grid[r][c] == 7:
                count += 1
            else:
                break
        # Pattern from analyzing demos:
        # 1 seven → color 2
        # 2-4 sevens → color 3
        # 5+ sevens → color 4
        # Check Demo 2: 0 sevens → 2, 3 sevens → 2, etc.
        if count == 1:
            color = 2
        elif count <= 4:
            color = 3
        else:
            color = 4
        row = [color] * cols
        result.append(row)
    return result
